## 4. 회귀 테스트

```go
func TestNormalizeHTML_HiddenContentExcluded(t *testing.T) {
	input := []byte(`<html><head><title>테스트</title></head><body>
<p>본문 텍스트</p>
<a href="https://example.com">공개 링크</a>
<table><tr><td>셀1</td><td>셀2</td></tr></table>
<script>
<a href="https://hidden.example.com">숨겨진 링크</a>
<table><tr><td>숨겨진 셀</td></tr></table>
숨겨진 텍스트
</script>
</body></html>`)

	title, text, tables, links, err := normalizeHTML(input, "https://example.com")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Title 검증
	if title != "테스트" {
		t.Errorf("title = %q, want %q", title, "테스트")
	}

	// Text 검증: 숨겨진 텍스트 제외
	if text != "본문 텍스트" {
		t.Errorf("text = %q, want %q", text, "본문 텍스트")
	}

	// Links 검증: 숨겨진 링크 제외
	if len(links) != 1 {
		t.Fatalf("len(links) = %d, want 1", len(links))
	}
	if links[0].Text != "공개 링크" || links[0].URL != "https://example.com" {
		t.Errorf("links[0] = %+v, want {공개 링크, https://example.com}", links[0])
	}

	// Tables 검증: 숨겨진 표 제외
	if len(tables) != 1 {
		t.Fatalf("len(tables) = %d, want 1", len(tables))
	}
	if len(tables[0]) != 1 || len(tables[0][0]) != 2 {
		t.Errorf("tables[0] = %+v, want [[셀1, 셀2]]", tables[0])
	}
}

func TestNormalizeHTML_NestedTableSeparateEntries(t *testing.T) {
	input := []byte(`<html><body>
<table>
<tr><td>외부 셀</td></tr>
<tr><td><table><tr><td>내부 셀</td></tr></table></td></tr>
</table>
</body></html>`)

	_, _, tables, _, err := normalizeHTML(input, "https://example.com")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// 중첩 테이블은 별도 항목으로 분리
	if len(tables) != 2 {
		t.Fatalf("len(tables) = %d, want 2 (outer + inner)", len(tables))
	}
}
```

