import math
import statistics

_ALLOWED_PHASES = ('loading', 'benchmark', 'post_idle')

def _is_finite_number(value):
    if isinstance(value, bool):
        return False
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False

def summarize_samples(samples, baseline_available):
    if not _is_finite_number(baseline_available) or float(baseline_available) < 0:
        raise ValueError('baseline_available must be a finite non-negative number')
    baseline = float(baseline_available)
    grouped = {phase: {} for phase in _ALLOWED_PHASES}
    if samples is None:
        samples = ()
    for row in samples:
        try:
            phase = row['phase']
            monotonic = row['monotonic']
            available = row['MemAvailable']
        except Exception:
            continue
        if not isinstance(phase, str) or phase not in _ALLOWED_PHASES:
            continue
        if not _is_finite_number(monotonic):
            continue
        if not _is_finite_number(available) or float(available) < 0:
            continue
        grouped[phase][float(monotonic)] = float(available)
    result = {}
    for phase in _ALLOWED_PHASES:
        points = grouped[phase]
        if not points: continue
        times = sorted(points)
        available_values = [points[t] for t in times]
        count = len(times)
        min_available = min(available_values)
        median_available = statistics.median(available_values)
        max_extra_memory = max(0.0, baseline - min_available)
        if count <= 1: max_gap = 0.0
        else: max_gap = max(next_t - prev_t for prev_t, next_t in zip(times, times[1:]))
        result[phase] = {'count': count, 'min_available': min_available, 'median_available': median_available, 'max_extra_memory': max_extra_memory, 'max_gap': max_gap}
    return result

